P.entries["subzone:bal-lal-ruins"] = {n="Bal'lal Ruins",s="Bal'lal Ruins sunt ruine antice ale trolilor Gurubashi, situate de-a lungul tarmului nord-vestic din Stranglethorn Vale, chiar la nord de Grom'gol Base Camp. Cu vedere spre apele tulburi ale Vile Reef, fundatiile de piatra in ruina sunt ocupate in prezent de troli Bloodscalp ostili.",h="Bal'lal Ruins sunt ruine antice ale trolilor Gurubashi, situate de-a lungul tarmului nord-vestic din...",kw={"Bal'lal Ruins","Bloodscalp","Grom'gol","Gurubashi","Stranglethorn Vale","Vile Reef"},ang={["faction:Horde"]="La mica distanta de-a lungul coastei fata de Grom'gol Base Camp, prezenta ostila a celor din Bloodscalp la Bal'lal este o permanenta bataie de cap pentru patrulele Horde de-a lungul tarmului.",["race:Troll"]="Pentru Troll din Darkspear aliniati cu Horde, locuri precum Bal'lal ofera o perspectiva sumbra asupra ruinelor gloriei stravechi Gurubashi, stapanite de triburi inrudite orbite de setea nestavilita de sange."},sec={{t="Un avanpost in ruina pe recif",b="Asezate pe coasta, la nord de Grom'gol Base Camp, Bal'lal Ruins sunt o alta ramasita a destramatului Gurubashi Empire. Odinioara parte a marii civilizatii a trolilor care stapanea sudul Azeroth, situl s-a degradat, ajungand sa fie alcatuit din ziduri de piatra acoperite de muschi si zidarie crapata. Ruinele se afla chiar langa Vile Reef si ofera o priveliste de la inaltime asupra apelor putin adanci si inselatoare de langa tarm. Astazi, trolii Bloodscalp agresivi stapanesc locul, aparand cu inversunare relicvele roase de vreme ale stramosilor lor de intrusi."}},faq={{q="Cine controleaza Bal'lal Ruins?",a="Ruinele sunt ocupate in prezent de membri ai tribului Bloodscalp, care isi apara cu inversunare teritoriul de straini, calatori si rivali deopotriva.",al={"cine locuieste aici","creaturi din ruinele Ballal","cine se afla la ruinele Ballal"}},{q="Unde se afla Bal'lal Ruins?",a="Ii poti gasi de-a lungul coastei de nord-vest a tinutului Stranglethorn Vale, chiar la nord de Grom'gol Base Camp, cu fata spre Vile Reef.",al={"locatia ruinelor Ballal","unde se afla ruinele Ballal","cum gasesc ruinele Ballal"}},{q="Ce istorie au aceste ruine?",a="La fel ca majoritatea structurilor de piatra raspandite prin Stranglethorn Vale, Bal'lal Ruins dateaza din vremea stravechiului Gurubashi Empire, inainte ca acesta sa se faramiteze in triburi de troll din jungla, divizate si razboinice.",al={"povestea lui Ballal","istoria ruinelor Ballal","cine a construit ruinele Ballal"}}},fp="13,269,31.527.0,27.153.0,36.151.0,33.193.0"}
P.entries["subzone:balia-mah-ruins"] = {n="Balia'mah Ruins",s="Balia'mah Ruins sunt ramasitele acoperite de muschi ale unei asezari Gurubashi stravechi din nordul Stranglethorn Vale. Aflate la est de Grom'gol Base Camp, peste rau, terasele de piatra care se naruie sunt revendicate si pazite in prezent de warriors din ostilul trib troll Skullsplitter.",h="Balia'mah Ruins sunt ramasitele acoperite de muschi ale unei asezari Gurubashi stravechi din nordul...",kw={"balia'mah","baliamah","gurubashi","ruine","skullsplitter","stranglethorn"},ang={["faction:Horde"]="Aflati chiar peste rau fata de Grom'gol Base Camp, cei din Skullsplitter de la Balia'mah reprezinta o amenintare permanenta pentru perimetrul pazit de cercetasii Horde si pentru liniile de aprovizionare.",["race:Troll"]="Pentru cei din Darkspear, sa strabata aceste trepte stravechi de piatra le aminteste de mandra civilizatie Gurubashi pe care au impartasit-o stramosii lor, dar si de factionalismul intunecat care a destramat societatea Troll din jungla."},sec={{t="O mostenire sfaramata",b="La fel ca multe dintre cladirile de piatra presarate prin jungla, Balia'mah este o ramasita a vastului Gurubashi Empire, care a stapanit candva o mare parte din sudul Eastern Kingdoms. Dupa caderea capitalei stravechi, teritoriul Gurubashi s-a faramitat in factiuni razboinice. Astazi, ruinele sunt o fortareata a tribului Skullsplitter, care apara cu inversunare terasele de piatra de bestiile ratacitoare, de ogrii vecini din movila Mosh'Ogg si de orice strain destul de nesabuit incat sa traverseze raul."}},faq={{q="Unde se afla Balia'mah Ruins?",a="Ruinele se afla in nordul Stranglethorn Vale, la est-sud-est, peste rau, de avanpostul Horde din Grom'gol Base Camp si la sud-vest de Mosh'Ogg Ogre Mound.",al={"locatia lui bali'mah","unde se afla balia mah","harta ruinelor baliamah"}},{q="Cine controleaza ruinele acum?",a="Ruinele sunt ocupate in prezent de tribul Skullsplitter, o factiune ostila de troli ai junglei care pazeste cu inversunare terasele stravechi de piatra.",al={"cine locuieste in balia mah","ce inamici se afla in balia mah","dusmanii din balia mah"}},{q="Care este istoria lui Balia'mah?",a="Complexul a fost construit in perioada de apogeu a Gurubashi Empire. Dupa prabusirea imperiului, locul a cazut in ruina, fiind in cele din urma acoperit de jungla si ramas in stapanirea triburilor troll supravietuitoare.",al={"povestea Balia Mah","cine a construit Balia Mah"}},{q="Sunt Skullsplitters din Balia'mah conectati cu alte tabere troll?",a="Da. Tribul Skullsplitter are mai multe tabere si ruine in nordul si centrul Stranglethorn Vale, unde duce un razboi teritorial neintrerupt impotriva triburilor rivale, precum Bloodscalp.",al={"skullsplitters din stranglethorn","skullsplitters din baliamah"}}},fp="15,283,20.498.0,38.164.0,33.148.0,33.200.0,67.205.0"}
